const githubProjectColors = ['project-sun', 'project-lilac', 'project-mint'];
const normalizeRepoUrl = (url = '') => url.replace(/\/$/, '').toLowerCase();
const safeExternalUrl = value => {
  try { const url = new URL(value); return ['https:', 'http:'].includes(url.protocol) ? url.href : ''; }
  catch { return ''; }
};
function mergeGithubProjects(repositories) {
  const byUrl = new Map(repositories.map(repo => [normalizeRepoUrl(repo.html_url), repo]));
  const curatedUrls = new Set(projects.map(project => normalizeRepoUrl(project.url)));
  const curated = projects.map(project => {
    const repo = byUrl.get(normalizeRepoUrl(project.url));
    if (!repo) return project;
    const homepage = safeExternalUrl(repo.homepage || '');
    const liveDemoNotIncluded = /\b(concept|no executable demo|demo is not included|demo not included|not deployable)\b/i.test(repo.description || '');
    const stack = [...new Set([repo.language, ...(repo.topics || [])].filter(Boolean))].slice(0, 3);
    const updatedAt = repo.pushed_at || repo.updated_at;
    return { ...project, desc: repo.description?.trim() || project.desc, stack: stack.length ? stack : project.stack, url: repo.html_url, demo: homepage || (liveDemoNotIncluded ? '' : project.demo), image: githubProjectImage(repo), updated: `GitHub · updated ${new Date(updatedAt).toLocaleDateString('en-IN', { month: 'short', year: 'numeric' })}` };
  });
  const excludedDescription = /\b(concept|showcase|legacy pointer|not included|not yet|no runnable|design notes|recorded demo)\b/i;
  const additional = repositories
    .filter(repo => repo.owner?.login?.toLowerCase() === 'kalyan870' && !repo.fork && !repo.archived)
    .filter(repo => repo.description?.trim() && !excludedDescription.test(repo.description))
    .filter(repo => !curatedUrls.has(normalizeRepoUrl(repo.html_url)))
    .map((repo, index) => {
      const stack = [...new Set([repo.language, ...(repo.topics || [])].filter(Boolean))].slice(0, 3);
      const updatedAt = repo.pushed_at || repo.updated_at;
      return {
        name: repo.name.replace(/[-_]+/g, ' '),
        label: (repo.language || 'GITHUB PROJECT').toUpperCase(),
        desc: repo.description.trim(),
        stack,
        color: githubProjectColors[index % githubProjectColors.length],
        updated: `GitHub · updated ${new Date(updatedAt).toLocaleDateString('en-IN', { month: 'short', year: 'numeric' })}`,
        url: repo.html_url,
        demo: safeExternalUrl(repo.homepage || ''),
        image: githubProjectImage(repo)
      };
    });
  return [...curated, ...additional];
}
function githubProjectImage(repo) {
  const owner = repo.owner?.login;
  if (!owner || !repo.name) return '';
  const cacheKey = (repo.pushed_at || repo.updated_at || 'latest').replace(/[^0-9TZ-]/g, '');
  return `https://opengraph.githubassets.com/${cacheKey}/${owner}/${repo.name}`;
}
function mapGithubEvent(event) {
  const repoName = event.repo?.name || 'GitHub repository';
  const shortRepo = repoName.split('/').at(-1);
  let title = '';
  let excerpt = '';
  let link = `https://github.com/${repoName}`;
  if (event.type === 'PushEvent') {
    const commits = event.payload?.commits || [];
    const message = commits[0]?.message?.split('\n')[0];
    title = message || `Updated ${shortRepo}`;
    excerpt = `${commits.length || event.payload?.size || 1} commit${(commits.length || event.payload?.size || 1) === 1 ? '' : 's'} pushed to ${repoName}.`;
    if (commits[0]?.sha) link = `${link}/commit/${commits[0].sha}`;
  } else if (event.type === 'ReleaseEvent' && event.payload?.release) {
    const release = event.payload.release;
    title = release.name || `Released ${release.tag_name || shortRepo}`;
    excerpt = release.body?.trim()?.slice(0, 220) || `Published ${release.tag_name || 'a release'} for ${repoName}.`;
    link = release.html_url || `${link}/releases`;
  } else if (event.type === 'CreateEvent') {
    title = `Created ${event.payload?.ref_type || 'repository'} ${event.payload?.ref || shortRepo}`;
    excerpt = `A new ${event.payload?.ref_type || 'repository'} was created in ${repoName}.`;
  } else return null;
  return { id: `github-${event.id}`, source: 'GitHub', title, excerpt, link, date: new Date(event.created_at).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' }), color: 'blue' };
}
function mapGithubCertificate(file) {
  const title = file.path.split('/').at(-1).replace(/\.[^.]+$/, '').replace(/[-_]+/g, ' ');
  const extension = file.path.split('.').at(-1).toLowerCase();
  return { title, issuer: 'GitHub · KalyanHub', date: 'Added from GitHub', accent: 'cert-blue', code: 'GITHUB / KALYANHUB', url: file.html_url, image: ['png', 'jpg', 'jpeg', 'webp'].includes(extension) ? file.download_url : '' };
}
